(() => {
 // Apply before the local editor initialises so future owner edits still win.
 for(const [id,fields] of Object.entries(traditionalRecipeUpdates)){
  const recipe=recipes.find(r=>r.id===id);if(!recipe)continue;
  Object.assign(recipe,fields);addMandarinRecipe(recipe);
 }
 const copy={photoCredit:['Reference photos may differ from the finished dish.','參考照片可能與食譜成品不同。','参考照片可能与食谱成品不同。'],risk2Title:['What you eat instead matters.','用甚麼替代碳水很重要。','用什么替代碳水很重要。']};
 for(const [key,values] of Object.entries(copy)){en[key]=values[0];cn[key]=values[1];mandarin[key]=values[2]}
 const seed=window.ROOT_RICE_EDITS;
 if(seed){for(const [key,values] of Object.entries(copy)){for(const [i,locale]of ['en','zh','zh-CN'].entries()){seed.text[locale]??={};seed.text[locale][key]=values[i]}}}
 function localized(en,zh){return lang==='en'?en:lang==='zh-CN'?simplifyChinese(zh):zh}
 function energyText(id){const n=recipeEnergyEstimates[id];return localized('About '+n.kcal+' kcal per serving ('+n.servings+' servings).','每份約 '+n.kcal+' 千卡（全份分 '+n.servings+' 份）。')}
 const renderBeforeEnergy=renderRecipes;
 renderRecipes=function(){renderBeforeEnergy();document.querySelectorAll('[data-recipe]').forEach(card=>{const id=card.dataset.recipe;if(!recipeEnergyEstimates[id])return;const note=document.createElement('p');note.className='card-energy';note.textContent=energyText(id);card.append(note)})};
 const openBeforeEnergy=openRecipe;
 openRecipe=function(id){openBeforeEnergy(id);const r=recipes.find(r=>r.id===id);const n=recipeEnergyEstimates[id];const detail=document.querySelector('#recipe-detail');
  // Retain the supplied photograph. Show a full-frame, natural-size view.
  if(r.photo){const image=document.createElement('img');image.className='recipe-original-photo';image.src=r.photo;image.alt=r.name[idx()];detail.querySelector('h2').after(image)}
  if(n){const box=document.createElement('aside');box.className='recipe-energy';const heading=document.createElement('h3');heading.textContent=localized('A guide to energy per portion','每份熱量參考');const value=document.createElement('p');value.className='energy-value';value.textContent=energyText(id);const assumptions=document.createElement('p');assumptions.textContent=lang==='en'?n.assumptions[0]:lang==='zh-CN'?simplifyChinese(n.assumptions[1]):n.assumptions[1];box.append(heading,value,assumptions);for(const pair of n.variants){const variant=document.createElement('p');variant.textContent=localized(pair[0],pair[1]);box.append(variant)}const caveat=document.createElement('p');caveat.textContent=localized('A rough ingredient-based kitchen estimate, not a measured nutrition value. Meat yield, oil, brands and portion size will change it.','按食材估算的家常參考，並非實測營養數值；可食肉量、用油、品牌和實際份量都會影響結果。');box.append(caveat);const benefit=detail.querySelector('.meal-benefit');if(benefit)benefit.after(box);else detail.querySelector('h2').after(box)}
  detail.querySelectorAll('.photo-credit').forEach(p=>p.textContent=localized('Photograph supplied in the owner’s edited website; preserved unchanged.','照片沿用網站主人提供的版本，原圖保留不變。'));
 };
 setLanguage();
})();
